actions.script:
function hasTurnstileIframe(){var iframes=document.querySelectorAll('iframe');for(var i=0;i<iframes.length;i++){if(iframes[i].src&&iframes[i].src.indexOf('challenges.cloudflare.com')!==-1)return true;}return false;}
async function requestTurnstileFocus(){return new Promise(function(resolve){var timeout=setTimeout(function(){window.removeEventListener('message',handler);resolve({success:false,reason:'timeout'});},20000);function handler(event){if(event.source===window&&event.data&&event.data.type==='TURNSTILE_FOCUS_RESPONSE'){clearTimeout(timeout);window.removeEventListener('message',handler);resolve(event.data);}}window.addEventListener('message',handler);window.postMessage({type:'TURNSTILE_FOCUS_REQUEST'},'*');});}
async function waitForModalWithFocusQueue(maxRetries){for(var attempt=0;attempt<maxRetries;attempt++){var modal=null;var startTime=Date.now();var focusRequested=false;var modalTimeout=40000;await new Promise(function(r){setTimeout(r,2000);});if(hasTurnstileIframe()&&!focusRequested){focusRequested=true;var focusResult=await requestTurnstileFocus();if(focusResult.reason==='modal_appeared'||focusResult.reason==='solved'||focusResult.reason==='no_turnstile'){modal=document.querySelector('.ReactModalPortal [role="dialog"]')||document.querySelector('[class*="ReactModal__Content"]');if(modal){var hasValues=modal.querySelectorAll('span[class*="css-vyilnr"]');if(hasValues&&hasValues.length>0){return{success:true,modal:modal,attempts:attempt+1};}}}}while(Date.now()-startTime<modalTimeout){modal=document.querySelector('.ReactModalPortal [role="dialog"]')||document.querySelector('[class*="ReactModal__Content"]');if(modal){var hasValues=modal.querySelectorAll('span[class*="css-vyilnr"]');if(hasValues&&hasValues.length>0){return{success:true,modal:modal,attempts:attempt+1};}}if(hasTurnstileIframe()&&!focusRequested&&Date.now()-startTime>5000){focusRequested=true;var focusResult=await requestTurnstileFocus();}await new Promise(function(r){setTimeout(r,500);});}if(attempt<maxRetries-1){window.location.reload();await new Promise(function(r){setTimeout(r,5000);});}}return{success:false,error:'modal timeout after '+maxRetries+' attempts',attempts:maxRetries};}
var currentDomain='${domains}'.split(',')[0].trim();var allResults=[];var waitResult=await waitForModalWithFocusQueue(3);if(!waitResult.success){allResults.push({domain_name:currentDomain,error:waitResult.error,turnstile_retries:waitResult.attempts});return JSON.stringify({total_domains:1,results:allResults});}var modal=waitResult.modal;await new Promise(function(r){setTimeout(r,3000)});var values=[].slice.call(modal.querySelectorAll('span[class*="css-vyilnr"]')).map(function(e){return e.textContent.trim()});var dofollow=[].slice.call(modal.querySelectorAll('p')).filter(function(p){return p.textContent.includes('dofollow')}).map(function(p){return p.textContent.trim()});var dr=values[0]||null;var backlinks=values[1]||null;var linking_websites=values[2]||null;var bl_df=dofollow[0]?dofollow[0].match(/(\d+)%/)?.[1]:null;var lw_df=dofollow[1]?dofollow[1].match(/(\d+)%/)?.[1]:null;allResults.push({domain_name:currentDomain,dr:dr,backlinks:backlinks,backlinks_dofollow_percentage:bl_df,linking_websites:linking_websites,linking_websites_dofollow_percentage:lw_df,turnstile_retries:waitResult.attempts});return JSON.stringify({total_domains:1,results:allResults});
